export const jlcByMpn: Record<string, any> = Object.fromEntries(
  importedParts.map((F) => {
    const { name, ...p } = F({} as any).props
    return [p.manufacturerPartNumber, p]
  }),
)
export const jlcById: Record<string, any> = Object.fromEntries(
  Object.values(jlcByMpn).map((p) => [p.supplierPartNumbers.jlcpcb[0], p]),
)
export function jlcPart(mpn: string) {
  const p = jlcByMpn[mpn]
  if (!p) throw new Error(`JLCPCB component not imported: ${mpn}`)
  return p
}
